<form method="post" action="<?= e(APP_URL.'/families/'.(int)$family['family_id'].'/update') ?>" class="space-y-6"><section class="rounded-xl border border-slate-200 bg-white p-6 shadow-sm"><div class="grid gap-5 md:grid-cols-2"><label class="text-sm font-medium text-slate-700">Registration number<input value="<?= e($family['registration_number']) ?>" disabled class="<?= $class ?> bg-slate-50"></label><label class="text-sm font-medium text-slate-700">PHM area<select required name="phm_area_id" class="<?= $class ?>"><option value="">Select area</option><?php foreach($phmAreas??[] as $a): ?><option value="<?= (int)$a['phm_area_id'] ?>" <?= (int)$value('phm_area_id')===(int)$a['phm_area_id']?'selected':'' ?>><?= e($a['phm_area_name']) ?></option><?php endforeach; ?></select></label><label class="text-sm font-medium text-slate-700 md:col-span-2">Address<textarea required name="address" rows="3" class="<?= $class ?>"><?= e($value('address')) ?></textarea></label><label class="text-sm font-medium text-slate-700">Status<select name="status" class="<?= $class ?>"><?php foreach(['Active','Inactive','Transferred'] as $s): ?><option <?= $value('status')===$s?'selected':'' ?>><?= e($s) ?></option><?php endforeach; ?></select></label><label class="text-sm font-medium text-slate-700 md:col-span-2">Remarks<textarea name="remarks" rows="4" class="<?= $class ?>"><?= e($value('remarks')) ?></textarea></label></div></section><div class="flex justify-end gap-3"><a href="<?= e(APP_URL.'/families/'.(int)$family['family_id']) ?>" class="rounded-lg border border-slate-300 px-4 py-2.5 text-sm font-semibold">Cancel</a><button class="rounded-lg bg-blue-600 px-5 py-2.5 text-sm font-semibold text-white">Save Family</button></div></form>
